# -*- coding: utf-8 -*-
"""Arabic text for the Rule page. TEXT = {key: translated inner HTML}."""
TEXT = {
"k34706326": "في قانون الصلاة",
"kc1ba8633": "ما تقوله مصادر الكنيسة في مقدار الصلاة، وفي الصلاة بحسب ما يستطيعه المرء. تنقل هذه الصفحة تلك المصادر؛ ولا تضيف إليها مشورة.",
"ka7965ff8": "<strong>اقرأ هذا أولاً.</strong> كل ما في Plithos مرجع، لا مقياس لك. الصلوات وقانون الصوم والساعات ورتب الخِدَم مبسوطة هنا كاملة لأنها ميراث الكنيسة وينبغي أن تكون في متناول الجميع. وبسطها كاملة ليس قولاً بأن أحداً ملزم بحفظها كلها.",
"kef5c7431": "القانون الذي تحفظه يعيّنه أبوك الروحي، بحسب معرفتك وطاقتك وظروفك. لا شيء في هذا الموقع يعلو على ذلك، ولا شيء هنا حكم على من يصلّي أقلّ مما هو مطبوع. ومن يقول الأبانا ثلاث مرات في اليوم ويعنيها، فهو يحفظ القانون الذي أعطته الكنيسة في القرن الأول.",
"kfd250c56": "تنقل هذه الصفحة ما تقوله المصادر ولا تضيف مشورة من عندها. وحيث لا تحمل جملة مرجعاً، فهي قول عن هذا الموقع، لا توجيه في صلاتك. التوجيه لكاهنك الذي يعرف حياتك؛ وهذا الموقع لا يعرفها.",
"kd06d4f8a": "ما كان عليه أقدم قانون في الحقيقة",
"kc90dad01": "أقدم كتاب مسيحي في التدبير وصل إلينا هو الديداخي، من نحو سنة 100. وقانون الصلاة فيه هو ثلاث مرات في اليوم الأبانا.",
"kadda83fe": "ثلاث مرات في اليوم صلّوا هكذا.",
"k513c7122": "الديداخي 8 &middot; ترجمة M. B. Riddle، 1886 &middot; <a href=\"/library#work=didache\">اقرأه في المكتبة</a>",
"k355facce": "والنص نفسه، قبل ذلك بفصلين، يذكر مبدأ القياس صراحةً، وليس هذا تخفيفاً حديثاً بل أقدم ما كتبته الكنيسة في هذا الأمر:",
"k0133b448": "فإن استطعت أن تحمل نير الرب كله، تكون كاملاً؛ وإن لم تستطع، فافعل ما تستطيع.",
"kec4ccf0b": "الديداخي 6 &middot; ترجمة M. B. Riddle، 1886 &middot; <a href=\"/library#work=didache\">اقرأه في المكتبة</a>",
"ka800cdac": "أما رتب الصلاة الأوفى في كتب الصلوات المتأخرة فقد نشأت بعد ذلك. والديداخي هو ببساطة أقدم قانون مكتوب تملكه الكنيسة، وهذا ما يطلبه.",
"kc8529ac1": "الكثرة ليست هي القياس",
"k605c07f5": "القديس يوحنا كاسيان، وهو يسجّل تعليم آباء مصر في مطلع القرن الخامس، يحذّر من حساب الصلاة بالأوقات التي يفردها المرء لها رسمياً:",
"kda219ca8": "فإنه يصلّي قليلاً جداً من اعتاد أن يصلّي في الأوقات التي يجثو فيها على ركبتيه فقط.",
"k87ef1fff": "القديس يوحنا كاسيان، المحاورات 10.14 &middot; ترجمة Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">اقرأه في المكتبة</a>",
"k6f06dcb5": "فقياس الصلاة عند كاسيان أوسع إذاً من الأوقات المعيّنة، والكلام موجّه إلى من يحصرونها فيها. وليس هو الذي أدخل هذه الفكرة. فالرسول كان قد أعطى القانون في صورة لا تسعها ساعة:",
"k9d16dd79": "مصلّين بكل صلاة وطلبة كل وقت في الروح وساهرين لهذا بعينه بكل مواظبة وطلبة لاجل جميع القديسين",
"kd45e4afe": "أفسس 6:18",
"k8ff6957a": "وأوجز من ذلك: <em>صلّوا بلا انقطاع</em> (1 تسالونيكي 5:17). قانون الأوقات المعيّنة يخدم ذلك؛ ولا يستنفده.",
"k94022491": "ترتيب، لا سُلَّم",
"k6f5ac9c2": "ما يلي ليس درجات يفرضها Plithos. بل هو ترتيب لما تحويه المصادر والكتب المتسلَّمة، بحسب ما يطلبه كلٌّ منها من اليوم. <strong>وأيُّ ذلك يناسب شخصاً بعينه فسؤال لأبيه الروحي، لا لهذه الصفحة.</strong>",
"kbd0070ec": "ليس سُلَّماً، والمدخل الأول هو عين السبب في ذلك. صلاة يسوع تأتي أولاً لأنها أقلُّ ما يطلب من ظروف الإنسان، لا لأنها أقلُّ ما يطلب من الإنسان نفسه. وهي بعينها ما يصفه الآباء الهدوئيون بأنه الصلاة كلها، وما يُعطى للمتقدّمين جداً عوضاً عن كل مكتوب. إنها قائمة على الطرفين معاً.",
"kec53651e": "صلاة يسوع",
"kd76e85df": "حين لا وقت ولا كتاب ولا هدوء - في السفر، وفي العمل، وفي المرض، وحين يتعذّر الوقوف أو الكلام بصوت",
"k15c8fcc6": "صلاة يسوع في صورتها الكاملة: <em>أيها الرب يسوع المسيح ابن الله، ارحمني أنا الخاطئ.</em> وحيث يكون هذا أيضاً كثيراً، يسمح الآباء بصور أقصر - <em>أيها الرب يسوع المسيح، ارحمني</em>، أو ببساطة <em>يا رب، ارحم</em>. لا تحتاج إلى كتاب ولا وقوف ولا صوت، ويمكن حملها خلال يوم عمل عادي.",
"k433c6e1a": "<a href=\"/prayers#s=heart\">صلاة يسوع، ومشورة الآباء في حفظها</a>",
"k0607d349": "تأتي أولاً لأنها تبقى في كل ظرف، لا لأنها أقلّ ما هنا. كاسيان، المحاورات 10.14: \"يصلّي قليلاً جداً من اعتاد أن يصلّي في الأوقات التي يجثو فيها على ركبتيه فقط.\"",
"k4fbd7571": "الأبانا، ثلاث مرات في اليوم",
"kccf34183": "قانون ثابت في أوقات ثابتة، حيث يمكن ذلك",
"k6c98a369": "قانون أقدم كتاب مسيحي في التدبير نملكه. وهو قانون صغير، لكنه قانون في أوقات ثابتة، ولذلك يطلب من اليوم المتقطّع أكثر مما تطلبه صلاة يسوع.",
"kb80095bf": "الديداخي 8.",
"k73f947ac": "قانون القديس سيرافيم ساروفسكي",
"kbeb11458": "لمن لا يترك عملهم مجالاً لقانون أطول",
"kba90cd4c": "عند النهوض، واقفاً أمام الأيقونات: الأبانا ثلاث مرات، و<em>يا والدة الإله العذراء افرحي</em> ثلاث مرات، وقانون الإيمان مرة واحدة. ثم إلى العمل، مردّداً صلاة يسوع بهدوء طوال الصباح، و<em>يا والدة الإله الفائقة القداسة خلّصيني</em> بعد الظهر. والقانون القصير نفسه مرة أخرى قبل النوم.",
"k6464f90a": "أعطاه القديس سيرافيم للعمّال وأرباب البيوت الذين لم يقدروا على حفظ صلوات الصباح والمساء الأوفى، ولم يعدَّه تنازلاً ينبغي الخروج منه. هو قانون صلوات ثابتة في أوقات ثابتة، مقروناً بصلاة تجري خلال يوم العمل، ولهذا يقف هنا لا أدنى من ذلك.",
"kc823332f": "القديس سيرافيم ساروفسكي، في إرشاداته للعلمانيين. أما الصلوات نفسها فهي في صفحة الصلوات.",
"k3041ac63": "صباحاً ومساءً",
"k225e3ccd": "القانون المعتاد في كتاب الصلوات للعلماني",
"kf4d2a2e5": "صلوات الصباح عند النهوض وصلوات المساء قبل النوم، تُقال بانتباه لا على عجل.",
"k98ad4446": "<a href=\"/prayers#s=daily\">صلوات الصباح والمساء</a>",
"k8ad36869": "كان القديس ثيوفانوس الحبيس يرى صلوات الصباح والمساء التي في كتاب الصلوات كافية تماماً للعلماني المبتدئ. انظر الملاحظة في صفحة الصلوات للمشورة الأوفى.",
"k4cecadd4": "مع الساعات",
"kefb7d0a1": "حيث يسمح اليوم بذلك",
"k8fb45542": "الخِدَم القصيرة خلال النهار، من الساعة الأولى إلى النوم.",
"k6b300612": "<a href=\"/prayers#s=hours\">الساعات</a>",
"k61610f0a": "صلوات الديداخي الثلاث اليومية هي بذرة هذه الدورة. والساعات كاملةً مذكورة في الأوروﻟﻮﭼﻴﻮﻥ.",
"kb3c5ab3d": "الاستعداد للمناولة",
"k8dbdf873": "قبل تناول الأسرار",
"kced3fbfd": "رتبة الاستعداد، والصلاتان اللتان تُقالان عند الكأس، والشكر بعدها. أما مقدار ما يُقال من الرتبة، وهل تُحفظ مساء اليوم السابق أم في الصباح، فيختلف بحسب التقليد ويعيّنه الأب الروحي. انظر أدناه ما يجعله الآباء الشرط الحقيقي للتقدّم.",
"k8f37e928": "<a href=\"/prayers#s=communion\">صلوات المناولة المقدسة في أقسامها الثلاثة</a>",
"k88dda4ec": "تختلف الممارسة اختلافاً ملحوظاً بين التقليد السلافي والتقليد اليوناني، في الاستعداد المنتظَر وفي مقدار تواتر مناولة المؤمنين.",
"ka6cba0b8": "حين لا تستطيع حفظ قانونك",
"k87db3602": "السفر والمرض والعمل الليلي والأولاد الصغار والحزن والإرهاق، كلها تقطع القانون. وأمران من النصوص السابقة يمسّان ذلك مباشرة.",
"k8dcf4ab6": "<strong>الديداخي لا يعرض القانون على أنه الكل أو لا شيء.</strong> فتعليمه ليس أن تحمل النير كله وإلا فلا شيء، بل إنه حيث لا يمكن حمل الكل، \"افعل ما تستطيع\".",
"ka4ac033d": "<strong>الصلاة ليست محصورة في أوقات الوقوف.</strong> هذه قوة كلمة كاسيان السابقة: فهو يوبّخ من يحسبون صلاتهم بأوقات جثوّهم على الركب فقط، وهذا يُدخل في الحساب الصلاة خارج تلك الأوقات لا يُخرجها منه. وصلاة يسوع في صورها القصيرة المتسلَّمة لا تقتضي كتاباً ولا هيئةً ولا صوتاً.",
"k1c9eeaa9": "ما يجعله الآباء شرطاً للتقدّم",
"keac4f2df": "رتبة الاستعداد خير حقيقي وميراث حقيقي. وليست هي ما يجعل الإنسان أهلاً للتناول. وفي هذا يتكلم الآباء صراحةً، وقد كتبوا قبل أن توجد أي رتبة استعداد مطبوعة بزمن طويل.",
"kc356b366": "القديس يوحنا الذهبي الفم، وهو يعظ على الرسالة إلى العبرانيين، يتناول بعينه سؤال كم مرة وكم مقداراً، ويأبى أن يجيب عليه بهذه الألفاظ:",
"kce69ff57": "فماذا إذاً؟ مَن نستحسن؟ الذين يتناولون مرة في السنة؟ أم الذين يتناولون مراراً كثيرة؟ أم الذين يتناولون نادراً؟ لا الذين مرة، ولا الذين كثيراً، ولا الذين نادراً، بل الذين يتقدّمون بضمير طاهر، من قلب طاهر، بسيرة لا لوم فيها. فليتقدّم هؤلاء دائماً؛ وأما الذين ليسوا كذلك فلا مرة واحدة.",
"k2d880e69": "القديس يوحنا الذهبي الفم، العظة 17 على العبرانيين &middot; ترجمة Frederic Gardiner &middot; <a href=\"/library#work=chrysostom-homilies-hebrews\">اقرأها في المكتبة</a>",
"k3448180a": "المعيار الذي يسمّيه الذهبي الفم هو حال الضمير. وهو لا يسمّي عدداً، لا للمناولات ولا للصلوات التي تُقال قبلها، ويطرح سؤال التواتر جانباً بوصفه السؤال الخطأ.",
"k4bc3e896": "والقديس يوحنا كاسيان يعالج النصف الآخر، وعنوان الفصل يقول ذلك بصراحة: <em>أنّا وإن اعترفنا بأننا لا نقدر أن نكون بلا خطيئة، فليس لنا مع ذلك أن نمتنع عن مناولة الرب.</em>",
"k3620ced2": "ومع ذلك ليس لنا أن نمتنع عن مناولة الرب لأننا نعترف بأنفسنا خطأة، بل بالحري نسرع إليها بأشدّ شوق لشفاء نفوسنا وتطهير أرواحنا، ونطلب بالأولى دواءً لجراحنا بتواضع الفكر والإيمان، إذ نحسب أنفسنا غير مستحقين لنيل نعمة بهذا القدر.",
"k99dd8e07": "وإلا لما استطعنا أن ننال المناولة باستحقاق ولا مرة في السنة، كما يفعل قوم يعيشون في الأديرة وينظرون إلى كرامة الأسرار السماوية وقداستها وقيمتها نظرةً تحملهم على الظن بأنه لا يجرؤ على نيلها إلا القديسون والأطهار، لا بالحري أنها هي التي تجعلنا قديسين وأطهاراً بنيلنا إياها. وبهذا عينه يقعون في ظنّ بالنفس وكِبْر أعظم مما يخالون أنهم يتحاشونه، لأنهم في الوقت الذي ينالون فيه يحسبون أنفسهم مستحقين للنيل.",
"kb8b440b1": "القديس يوحنا كاسيان، المحاورات 23.21 &middot; ترجمة Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">اقرأه في المكتبة</a>",
"kcab416e7": "وحجّة كاسيان أن الامتناع عن شعور بعدم الاستحقاق هو نفسه الظنّ الأكبر بالنفس، إذ إن الممتنع حتى يصير مستحقاً يفترض أنه في يوم آخر كان سيكون كذلك. وفي مقابل ذلك يضع ما يقول إن الأسرار من أجله: لا مكافأةً للأطهار فعلاً، بل الوسيلة التي بها، على حدّ قوله، تجعلنا قديسين وأطهاراً بنيلنا إياها.",
"k1ceaa3c4": "ما تجعل الكنيسة المتناوِل يقوله عن نفسه",
"k15496498": "ليس هذا خفضاً للقياس. بل هو القياس، والكنيسة تضعه في فم كل من يتقدّم. فالاعتراف الذي يُقال عند الكأس بصوت عالٍ من الجماعة كلها لا يقول إن قائله قد بلغ:",
"kffb87ae9": "أومن يا رب وأعترف أنك أنت هو المسيح حقاً، ابن الله الحي، الذي أتى إلى العالم ليخلّص الخطأة الذين أولهم أنا.",
"kd40a122c": "الصلاة قبل التناول &middot; على أثر 1 تيموثاوس 1:15 &middot; <a href=\"/prayers#s=communion\">اقرأها في كتاب الصلوات</a>",
"k91d95d94": "وكلمات الرسول نفسه هي <em>المسيح يسوع جاء إلى العالم ليخلّص الخطأة الذين أولهم أنا</em>، ولم تتركها الكنيسة في الرسالة. بل وضعتها عند الكأس وأعطتها لكل متناوِل ليقولها بصيغة المتكلم، في اليوم الذي يتناول فيه. والقديسون هم الذين قالوا هذه الجملة وعنوها، لا الذين بلغوا حدّاً كفّت عنده عن الانطباق عليهم. النعمة تُعطى؛ والمطلوب منا أن نجيب، وأن نحفظ الوصايا التي أُعطيت لنا، وأن نظلّ نجيب بعد أن نكون قد أخفقنا في حفظها.",
"kf78cb40a": "ما يعنيه هذا عملياً",
"k87e5b047": "<strong>الرتبة ليست من الشروط القانونية.</strong> فلا قانون في الكنيسة يوجبها قبل التناول، والتسلسل المطبوع الثابت متأخر عن القوانين؛ ومقدار ما يُقال منها يعيّنه الأب الروحي.",
"k0e542bbd": "<strong>أما ما يسمّيه التقليد فعلاً</strong> قبل الكأس فهو ضمير لا يستقرّ في خطيئة غير متاب عنها، والسلام مع القريب، والصوم الإفخارستي، وطاعة الأب الروحي في أمر الاعتراف. وكاسيان يعالج مباشرةً حالة من امتنع بدافع عدم الاستحقاق، في الفقرة السابقة؛ والذهبي الفم يعالج من يحسب بالأعداد.",
"k21c606eb": "<strong>الصوم الإفخارستي قانوني لا عُرفي.</strong> فالمجموعة الأفريقية أوجبته، وسمحت باستثناء واحد في السنة، في اليوم الذي يُذكر فيه عشاء الرب:",
"k253a3d17": "ألا تُقام أسرار المذبح إلا من الصائمين، خلا الذكرى السنوية الواحدة لتذكار عشاء الرب؛ فإن كان تذكار بعض الراقدين، أساقفةً كانوا أو غيرهم، سيُقام بعد الظهر، فليكن بالصلوات فقط، إن كان الخُدّام قد أكلوا.",
"kb289f398": "المجموعة الأفريقية (419)، القانون 41 &middot; ترجمة Henry R. Percival، 1900 &middot; <a href=\"/library#work=canons-ecumenical\">اقرأه في المكتبة</a>",
"kfd9e4371": "وأخذ المجمع التروللي بهذا القانون ورفع الاستثناء:",
"k97125890": "يقول قانون لمجمع قرطاجنة إن أسرار المذبح المقدسة لا تُقام إلا من الصائمين، خلا يوم واحد في السنة يُحتفل فيه بعشاء الرب. وفي ذلك الحين، ربما بسبب بعض الظروف النافعة للكنيسة في تلك المواضع، استعمل الآباء القديسون أنفسهم هذا التدبير. ولكن إذ لا شيء يحملنا على ترك الدقة، نرسم أن يُتبَع التقليد الرسولي والآبائي؛ ونحدّد أنه لا يجوز حلّ الصوم في اليوم الخامس من الأسبوع الأخير من الصوم الأربعيني، فيُهان بذلك الصوم كله.",
"k5c17110d": "المجمع التروللي، الخامس السادس (692)، القانون 29 &middot; ترجمة Henry R. Percival، 1900 &middot; <a href=\"/library#work=canons-ecumenical\">اقرأه في المكتبة</a>",
"k4b650236": "ما توجبه القوانين هو الصوم. أما حسابه من منتصف الليل السابق فهو العرف الذي يحمله، وهو الممارسة المعتادة في كل ولاية كنسية. وحيث تُقام القداسات مساءً، كالقداس السابق تقديسه وكما يمكن أن تكون قداسات الميلاد والظهور الإلهي وخميس الأسرار وسبت النور، يعيّن الأسقف المدة بدلاً من حسابها من منتصف الليل. وأما الدواء الذي يجب تناوله والمرض والحمل والطفولة والشيخوخة المتقدمة فيعالجها الأب الروحي. والسؤال ليس كالإعفاء، وليس أيٌّ منهما سبباً للبقاء بعيداً عن الكأس.",
"kc182b483": "<strong>والصلاتان اللتان تُقالان عند الكأس</strong> - \"أومن يا رب وأعترف\" و\"عشاءك السري\" - تُقالان بصوت عالٍ مع الجماعة كلها في أكثر الرعايا.",
"kaebd6892": "القوانين رهبانية في صورتها؛ أما الحياة التي تطلبها فليست كذلك",
"keedea2a4": "كل قانون ثابت مطبوع في كتاب صلوات بلغ صورته الحاضرة في دير تقريباً، ولهذا قد يُقرأ الاستعداد كأنه موجَّه إلى غيرك. والاعتراض قديم إلى حدّ أن القديس يوحنا الذهبي الفم يضعه في أفواه سامعيه قبل أن يجيب عليه:",
"k3f765fe1": "لست، تقول، من الرهبان، بل لي امرأة وأولاد وتدبير بيت. وهذا عينه هو الذي أفسد كل شيء، ظنّك أن قراءة الكتب الإلهية لأولئك وحدهم، مع أنك أحوج إليها منهم بكثير. فإن الساكنين في العالم والذين ينالون كل يوم جراحاً، هؤلاء هم أشدّ الناس حاجة إلى الأدوية.",
"kebad4fa3": "القديس يوحنا الذهبي الفم، العظة 2 على متى &middot; ترجمة George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">اقرأها في المكتبة</a>",
"k5eee983b": "ويقول الشيء نفسه عن نمط الحياة ذاته، ويقوله رفضاً لأن يجعل البرية شريعة:",
"k00cd498f": "لست أجعل شريعةً أن تحتلّوا الجبال والبراري، بل أن تكونوا صالحين ومتبصّرين وأعفّاء، ساكنين في وسط المدينة.",
"kc7ddce00": "القديس يوحنا الذهبي الفم، العظة 7 على متى &middot; ترجمة George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">اقرأها في المكتبة</a>",
"k99a23dda": "وفي العظات على الرسالة إلى رومية يتناول فكرة أن الحياة العادية هي العنوان الخطأ للوصايا، فيراها اتهاماً للإيمان لا وصفاً له:",
"k91017238": "فإن لم يكن ممكناً لمن يعيش في وسط المدن أن يكون تلميذاً، فذلك اتهام ثقيل لهذا النهج، أي أن علينا أن نترك المدن ونهرب إلى البراري. ولكن أرِني رجلاً له امرأة وأولاد وأهل بيت، وهو مع ذلك يطلب الحكمة. فماذا نقول لكل هذا؟ أفلا يجب أن نطأطئ رؤوسنا ونخجل؟ فإن المسيح لم يعطنا وصية كهذه؛ بل ماذا؟ فليضئ نوركم قدام الناس، لا الجبال والبراري والقفار والمواضع النائية.",
"kafb2fb07": "القديس يوحنا الذهبي الفم، العظة 26 على رومية &middot; ترجمة J. B. Morris وW. H. Simcox &middot; <a href=\"/library#work=chrysostom-homilies-romans\">اقرأها في المكتبة</a>",
"ke1ee6e3e": "وهو يحترز، في الجملة التي تليها، من أن يُفهم كأنه يحطّ من شأن الرهبان: يقول إنه يتكلم \"لا شتماً للذين أخذوا الجبال، بل نَوحاً على الساكنين في المدن، لأنهم نفوا منها الفضيلة.\" الراهب يسلّم مشيئته لشيخ. والعلماني أُعطي الشيء نفسه ليسلّمه، في زواج، وفي عمل لم يخترْه، وفي الصبر الذي يكلّفه البيت، ويُطلب منه في صورة لا يستطيع قانون أن يطبعها سلفاً.",
"ka438020e": "الصوم والاعتراف وسائر الاستعداد",
"k67ac3841": "الاستعداد ليس صلاة فقط. وصوم الأربعاء والجمعة أقدم أجزائه، وهو في الفصل نفسه من الديداخي الذي يعطي قانون الصلاة:",
"ke069eea2": "ولا تكن أصوامكم مع المرائين؛ فإنهم يصومون اليوم الثاني والخامس من الأسبوع؛ وأما أنتم فصوموا اليوم الرابع ويوم الاستعداد (الجمعة). ولا تصلّوا كالمرائين، بل كما أمر الرب في إنجيله، هكذا صلّوا: أبانا الذي في السماوات...",
"k4e4ee152": "والتحذير في هذا الموضع يتناول الشطرين معاً: لا عدم الصوم، بل الصوم <em>كالمرائين</em>؛ ولا عدم الصلاة، بل الصلاة <em>كالمرائين</em>. والديداخي يعطي القانونين في نفَس واحد ويقيّد كلاً منهما بالطريقة نفسها.",
"k901f0415": "الاعتراف قبل المناولة منتظَر في بعض التقاليد وغير منتظَر في غيرها، والفرق قديم لا مسألة تراخٍ. ويستحق أن يُبسَط، لأن من تعلّم الاستعداد في تقليد ثم وجد نفسه في رعية التقليد الآخر قد يحسب فرق العادة حكماً عليه.",
"k345e3232": "<strong>في الكنائس السلافية</strong> - الروسية والروسية خارج الحدود وكنيسة أميركا الأرثوذكسية والأوكرانية والصربية - يُنتظر الاعتراف عادةً قبل كل مناولة. ويشمل الاستعداد بحسب العرف القوانين الثلاثة، للمخلّص ولوالدة الإله وللملاك الحارس، وكثيراً ما يشمل المديح لربنا يسوع الحلو، فضلاً عن صلوات الاستعداد؛ والحضور في السهرانية أو صلاة الغروب في المساء السابق منتظَر بوصفه جزءاً من الاستعداد لا عبادةً منفصلة.",
"k3c46f09c": "<strong>وفي الممارسة اليونانية والأنطاكية والرومانية</strong> يكون الاعتراف في الأغلب منفصلاً عن المناولة ويُحفظ في فترات يعيّنها الأب الروحي، وكثيراً ما يكون في الأصوام الأربعة. والاستعداد يعني في الأغلب صلوات الاستعداد لا مجموعة القوانين والمديح كاملة، وخدمة المساء يُحثّ عليها بقوة من غير أن تُجعل شرطاً للتناول.",
"kbf226744": "وكلاهما ممارسة راسخة لكنائس محلية بأسرها، وكلٌّ منهما محفوظ تحت إرشاد إكليروس تلك الكنيسة. وقانون المرء هنا يأتي من أبيه الروحي هو، لا من الوصف الذي صادف أن قرأه أولاً.",
"k7edee590": "كلمة ختامية في القياس",
"k95bf9581": "القانون موجود لئلا نستسلم للكسل من جهة، ولا ندفع أنفسنا فوق طاقتنا من جهة أخرى. وكان القديس ثيوفانوس الحبيس يعلّم أن للطريق حفرتين: عن اليمين غيرة بلا معرفة، وعن اليسار كسل. والإفراط يبلغ بالمبتدئ إلى الإنهاك واليأس حين يخفق، وإلى الكبرياء حين ينجح. وكتب القديس إغناطيوس بريانتشانينوف أن القانون موجود لأجلك؛ ولست أنت موجوداً لأجل القانون، بل تحيا للرب، وعليك أن تحفظ حرية التمييز.",
"kd192a6bd": "ابدأ بالقليل. أن تقول صلوات قليلة بانتباه خير من أن تمرّ بكثير على عجل. إن كان لك أب روحي، فاحفظ القانون الذي يعطيك ولا تغيّر شيئاً بغير بركته؛ وإن لم يكن لك بعد، فاحفظ قانوناً معتدلاً على قدر طاقتك واطلب أباً كهذا. ولا كتاب ولا صفحة تقوم مقام أب حيّ في المسيح.",
"kb6eb659b": "مأخوذ عن القديس ثيوفانوس الحبيس، في قانون الصلاة، وعن القديس إغناطيوس (بريانتشانينوف) في قانون الصلاة &middot; <a href=\"/#guide\">وأيضاً في الدليل</a>",
"keda0cc2f": "لا شيء في هذا الموقع ميزان يُوزن به أحد. إنه مكتبة وتقويم.",
"kc89cd31d": "قانون الصلاة هو مقدار محدّد من الصلاة يُحفظ في أوقات محدّدة. تعرض هذه الصفحة ما تقوله مصادر الكنيسة في المقدار، والأشكال التي يتّخذها القانون عادةً.",
"k36c2948e": "<strong>اقرأ هذا أولاً.</strong> القانون الذي تحفظه يعيّنه أبوك الروحي، بحسب قوّتك وظروفك. ما هو مطبوع هنا هو الميراث، لا مقياس يُحاسَب به أحد. مَن يتلو الأبانا ثلاث مرّات في اليوم ويعنيها حقًّا يحفظ القانون الذي أعطته الكنيسة في القرن الأول.",
"k530f73b4": "من أين جاء القانون",
"kc776efc1": "قبل ذلك بفصلين يذكر النصّ نفسه المقياس، وهو أقدم ما كتبته الكنيسة في هذا الأمر:",
"k81f4ff1a": "كلّ ما في كتب الصلوات جاء بعد ذلك. وقانون الساعات المحدّدة يخدم الصلاة من غير أن يستنفدها: قول الرسول <em>صلّوا بلا انقطاع</em> (1 تسالونيكي 5:17) هو المقياس الأوسع، والقدّيس يوحنّا كاسيانوس، إذ يدوّن آباء مصر، يقولها بحدّة.",
"k071c623f": "الأشكال التي يتّخذها القانون",
"k28364d47": "هذه هي الأشكال التي يتّخذها عادةً قانون العلماني، مرتّبةً بحسب ما يطلبه كلٌّ منها من اليوم. وليست سُلّمًا يُصعد عليه: فالأول هو ما يصفه الآباء الهدوئيّون بأنّه الصلاة كلّها، وما يُعطى للأبعد تقدّمًا عوضًا عن كلّ مكتوب. <strong>وأيّها يخصّك سؤالٌ لأبيك الروحي.</strong>",
"kf8b6b4bc": "صلاة بلا أوقات محدّدة &middot; حين لا وقت ولا كتاب ولا هدوء",
"k491be6c4": "<em>أيّها الربّ يسوع المسيح، ابن الله، ارحمني أنا الخاطئ.</em> وحيث يكون هذا أيضًا كثيرًا، يسمح الآباء بصيغ أقصر - <em>أيّها الربّ يسوع المسيح، ارحمني</em>، أو ببساطة <em>يا ربّ ارحم</em>. لا تحتاج إلى كتاب ولا وقوف ولا صوت، ويمكن حملها في يوم عمل. وتأتي أولاً لأنّها تصمد في كلّ ظرف، لا لأنّها أقلّ ما ههنا.",
"k2d14e1b1": "قانون قصير في أوقات محدّدة &middot; الديداخي",
"k25c1035a": "صلوات محدّدة مقرونة بصلاة تمتدّ في اليوم &middot; لمن لا يترك لهم عملهم مجالاً لأكثر",
"k5cacd522": "أعطاه القدّيس سيرافيم للعمّال وأرباب البيوت الذين لم يقدروا على حفظ الصلوات الأوفى، ولم يعامله كتنازلٍ يُخرَج منه بالنموّ.",
"kc0703990": "صلوات الصباح عند النهوض وصلوات المساء قبل النوم، تُتلى بانتباه لا بعجلة. وكان القدّيس ثيوفانوس الحبيس يرى أنّها كافية تمامًا لعلمانيّ مبتدئ.",
"k030dfcd7": "الدورة اليوميّة للخدم &middot; حيث يسمح النهار",
"k129ba7c3": "الخدم القصيرة في أثناء النهار، من الساعة الأولى إلى النوم الصغير. وصلوات الديداخي الثلاث اليوميّة هي بذرة هذه الدورة؛ والساعات الكاملة في كتاب الساعات.",
"k6ca85803": "قانون عند المناسبة &middot; قبل تناول الأسرار",
"kc26de5d2": "السفر والمرض والعمل الليلي والأولاد الصغار والحزن والإعياء، كلّها تقطع القانون. ونصّان ممّا تقدّم يمسّان ذلك مباشرةً. فالديداخي لا يعرض قانونه على أنّه الكلّ أو لا شيء: حيث لا يُحتمل النير كلّه، \"فما تقدر عليه فافعله\". وكاسيانوس يوبّخ الذين لا يحسبون صلاتهم إلّا بأوقات جثوّهم على الركب - وهذا يُدخل في الحساب الصلاة خارج تلك الأوقات، ولا يُخرجها منه.",
"k892d0484": "خدمة الاستعداد خيرٌ حقيقيّ وميراثٌ حقيقيّ. لكنّها ليست ما يجعل الإنسان أهلاً للتناول. والقدّيس يوحنّا الذهبيّ الفم يتناول مسألة كم مرّة وكم مقدارًا، ويأبى أن يجيب عنها بتلك الألفاظ:",
"k74472bee": "المقياس الذي يسمّيه هو حال الضمير، لا عدد. والقدّيس يوحنّا كاسيانوس يعالج الشطر الآخر تحت عنوان فصلٍ يقول الأمر صراحةً: <em>أنّنا وإن اعترفنا بأنّنا لا نقدر أن نكون بلا خطيئة، فلا ينبغي مع ذلك أن نمتنع عن مناولة الربّ.</em>",
"k89f08ec2": "والامتناع عن شعور بعدم الاستحقاق هو في ذاته، كما يحتجّ، الجرأة الأكبر: فالممتنع حتّى يصير مستحقًّا يفترض أنّه في يومٍ آخر كان يكون كذلك. والأسرار ليست مكافأةً للأطهار، بل هي، بحسب قوله، تجعلنا قدّيسين وأطهارًا بتناولنا إيّاها.",
"ke31bdf96": "وليس هذا تخفيضًا للمقياس. بل هو المقياس، والكنيسة تضعه في فم كلّ من يتقدّم:",
"kfbddc832": "وكلمات الرسول نفسه هي <em>أنّ المسيح يسوع جاء إلى العالم ليخلّص الخطأة الذين أوّلهم أنا</em>، والكنيسة لم تتركها في الرسالة: بل أخذتها إلى الخدمة، وأعطتها لكلّ متناول ليقولها بصيغة المتكلّم، في يوم تناوله. والقدّيسون هم الذين قالوا تلك الجملة وعنَوها، لا الذين بلغوا حدًّا كفّت عنده عن الانطباق.",
"kdc0a783e": "<strong>وما يسمّيه التقليد</strong> هو ضميرٌ لا يستقرّ في خطيئة غير معترَف بها، وسلامٌ مع القريب، والصوم الإفخارستيّ، وطاعة الأب الروحي في أمر الاعتراف.",
"keeb5d497": "<strong>الصوم الإفخارستيّ قانونيّ لا عاديّ.</strong> المجموعة الإفريقيّة سنة 419 كانت تطلبه وتسمح باستثناء واحد في السنة؛ ومجمع ترولّو أخذ ذلك القانون وأزال الاستثناء:",
"k718a2fab": "ولكن بما أنّه لا شيء يحملنا على ترك الحفظ الدقيق، نرسم أن يُتبع التقليد الرسوليّ والآبائيّ، ونحدّد أنّه لا يجوز حلّ الصوم في اليوم الخامس من الأسبوع الأخير من الصوم الكبير، فيُهان بذلك الصومُ كلّه.",
"k2426bb65": "ما تطلبه القوانين هو الصوم. وحسابه من منتصف الليل السابق هو العادة التي تحمله. وحيث تُقام القدّاسات مساءً - قدّاس السابق تقديسه، وقدّاسات الميلاد والظهور الإلهيّ وخميس الأسرار وسبت النور - يعيّن الأسقف المدّة بدل أن تُحسب من منتصف الليل. والأدوية التي يجب تناولها، والمرض، والحبل، والطفولة، والشيخوخة العالية، يعالجها الأب الروحي. والسؤال ليس كالإعفاء، وليس أيّ منهما سببًا للابتعاد عن الكأس.",
"ka41be440": "وهو يأبى أن يجعل البرّيّة شريعة - \"لست أجعل لكم شريعةً أن تسكنوا الجبال والبراري، بل أن تكونوا صالحين ومترفّقين وعفيفين، ساكنين في وسط المدينة\" - ويحترز من أن يُفهم كمن يزدري الرهبان، إذ يقول إنّه يتكلّم \"لا شتمًا للذين أخذوا الجبال، بل نوحًا على الساكنين في المدن، لأنّهم نفوا الفضيلة من هناك\". الراهب يسلّم مشيئته لشيخ. والعلمانيّ يُعطى الشيء عينه ليسلّمه، في زواج، وفي عملٍ لم يخترْه، وفي الصبر الذي يكلّفه البيت، ويُطلب منه في صورةٍ لا يقدر قانونٌ أن يطبعها سلفًا.",
"ke5795f78": "الصوم والاعتراف",
"k6602f295": "الاستعداد ليس صلاةً فحسب. وصوم الأربعاء والجمعة أقدم أجزائه، وهو في الفصل عينه من الديداخي الذي يعطي قانون الصلاة - وهو يقيّد الشطرين بالطريقة عينها، محذّرًا لا من ترك الصوم أو الصلاة، بل من فعل أيّهما <em>كالمرائين</em>.",
"k78388bd9": "الاعتراف قبل المناولة متوقَّع في بعض التقاليد وغير متوقَّع في غيرها، والفرق قديم وليس مسألة تساهل. ومن تعلّم الاستعداد في تقليدٍ ثمّ وجد نفسه في رعيّة التقليد الآخر قد يأخذ بسهولة اختلاف العادة حكمًا عليه.",
}
